#include "jerico/bed.hpp"
#include "jerico/export.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
int main(int argc,char**argv){try{if(argc<3)throw std::runtime_error("Usage: jerico_bed_cli recipe.json output-directory [texture-resolution=512]");jerico::Json r;std::ifstream(argv[1])>>r;auto s=jerico::evaluate_bed(jerico::build_bed(r));auto errors=jerico::validate_scene(s);auto contacts=jerico::validate_bed(s);if(!errors.empty()||!contacts.empty())throw std::runtime_error(errors.dump()+contacts.dump());std::filesystem::path out=std::filesystem::absolute(argv[2]);std::filesystem::create_directories(out);jerico::bake_bed_materials(s,(out/"textures").string(),argc>3?std::stoi(argv[3]):512);std::ofstream(out/"scene.json")<<s.dump();jerico::write_glb(s,(out/"bed.glb").string());jerico::write_obj_mtl(s,(out/"bed.obj").string());size_t vertices=0,faces=0;for(auto&p:s["parts"]){vertices+=p["vertices"].size();faces+=p["faces"].size();}jerico::Json report={{"preset",s["recipe"]["preset"]},{"parts",s["parts"].size()},{"vertices",vertices},{"faces",faces},{"native_cpp",true},{"texture_resolution",argc>3?std::stoi(argv[3]):512},{"shared_materials",s["metadata"]["native_material_bake"]["shared_material_count"]},{"geometry_errors",errors},{"contact_errors",contacts}};std::ofstream(out/"report.json")<<report.dump(2);std::cout<<report.dump(2)<<'\n';}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
